/bin/bash -lc "node --input-type=module - <<'EOF'
import { buildReport } from './src/report.js';
const cases = {
  comma: [{name:'Acme, Inc.', total:10}],
  quote: [{name:'O\"Reilly', total:10}],
  newline: [{name:'Line\\nItem', total:10}],
  missing: [{name:'No total'}],
  nan: [{name:'Bad', total:NaN}],
  nullRows: [null],
};
for (const [name, rows] of Object.entries(cases)) {
  try { console.log(name, JSON.stringify(buildReport(rows))); }
  catch (e) { console.log(name, e.constructor.name + ': ' + e.message); }
}
EOF"

